-- =====================================================================
-- Rulebook for the Rule-cited autocomplete (V5RC OVERRIDE quick reference).
-- Run AFTER schema.sql (which creates the rules table).
-- Safe to re-run: re-importing updates each rule's description.
-- "VEX" removed from descriptions; college (VEX U) rules omitted.
-- =====================================================================
on conflict (event_id, code) do update set
  description = excluded.description, category = excluded.category, ord = excluded.ord;
